DEMO_WORKSPACE = "00000000-0000-4000-8000-000000000000"
SCHEMA_VERSION = 2


def statements(postgres):
    sequence = (
        "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
        if postgres
        else ("INTEGER PRIMARY KEY")
    )
    return (
        """CREATE TABLE IF NOT EXISTS products (
            id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, sku TEXT NOT NULL,
            data TEXT NOT NULL, sample TEXT, updated_at TEXT NOT NULL,
            revision INTEGER NOT NULL DEFAULT 1
        )""",
        """CREATE UNIQUE INDEX IF NOT EXISTS workspace_sku
            ON products(workspace_id,lower(sku))""",
        """CREATE TABLE IF NOT EXISTS product_revisions (
            product_id TEXT NOT NULL REFERENCES products(id), revision INTEGER NOT NULL,
            data TEXT NOT NULL, actor_id TEXT, created_at TEXT NOT NULL,
            PRIMARY KEY (product_id, revision)
        )""",
        """CREATE TABLE IF NOT EXISTS reviews (
            product_id TEXT NOT NULL REFERENCES products(id), id TEXT NOT NULL, data TEXT NOT NULL,
            PRIMARY KEY (product_id, id)
        )""",
        """CREATE TABLE IF NOT EXISTS tasks (
            id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, request_id TEXT NOT NULL,
            submitted_by TEXT, retry_of TEXT, status TEXT NOT NULL,
            input TEXT NOT NULL, snapshot TEXT NOT NULL, template_version INTEGER NOT NULL,
            insights TEXT, mode TEXT, error TEXT,
            created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
            attempt INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_until DOUBLE PRECISION,
            worker_id TEXT, run_metadata TEXT, UNIQUE (workspace_id, request_id)
        )""",
        """CREATE INDEX IF NOT EXISTS task_lease_queue ON tasks(status, lease_until, created_at)""",
        """CREATE INDEX IF NOT EXISTS workspace_tasks ON tasks(workspace_id, created_at, id)""",
        f"""CREATE TABLE IF NOT EXISTS events (
            seq {sequence}, task_id TEXT NOT NULL REFERENCES tasks(id), data TEXT NOT NULL
        )""",
        """CREATE INDEX IF NOT EXISTS task_event_sequence ON events(task_id, seq)""",
        """CREATE TABLE IF NOT EXISTS versions (
            task_id TEXT REFERENCES tasks(id), version INTEGER, draft TEXT NOT NULL,
            checks TEXT NOT NULL, approved_at TEXT, created_at TEXT NOT NULL, author_id TEXT,
            review_status TEXT NOT NULL DEFAULT 'draft', submitted_at TEXT, submitted_by TEXT,
            submit_note TEXT, decided_at TEXT, decided_by TEXT, review_note TEXT,
            PRIMARY KEY (task_id, version)
        )""",
        f"""CREATE TABLE IF NOT EXISTS audit_log (
            id {sequence}, workspace_id TEXT NOT NULL, actor_id TEXT,
            action TEXT NOT NULL, resource_id TEXT NOT NULL, details TEXT NOT NULL,
            created_at TEXT NOT NULL
        )""",
        """CREATE INDEX IF NOT EXISTS workspace_audit ON audit_log(workspace_id,id)""",
        """CREATE TABLE IF NOT EXISTS workers (
            id TEXT PRIMARY KEY, seen DOUBLE PRECISION NOT NULL
        )""",
        """CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY)""",
    )


def migrate(db):
    if db.postgres:
        db.execute("SELECT pg_advisory_xact_lock(412970612)")
    db.execute("CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY)")
    version = db.execute("SELECT version FROM schema_version").fetchone()
    if version is not None:
        if version["version"] != SCHEMA_VERSION:
            raise RuntimeError("数据库版本与此版本的工作台不兼容。")
        return
    tables = ("products", "reviews", "tasks", "events", "versions")
    legacy = (
        not db.postgres
        and db.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='products'"
        ).fetchone()
    )
    if legacy:
        for table in tables:
            db.execute(f"ALTER TABLE {table} RENAME TO legacy_{table}")
    for statement in statements(db.postgres):
        db.execute(statement)
    if legacy:
        migrate_legacy(db)
        for table in reversed(tables):
            db.execute(f"DROP TABLE legacy_{table}")
    db.execute("INSERT INTO schema_version VALUES (?)", (SCHEMA_VERSION,))


def migrate_legacy(db):
    db.execute(
        """INSERT INTO products (id,workspace_id,sku,data,sample,updated_at)
        SELECT id,?,sku,data,sample,updated_at FROM legacy_products""",
        (DEMO_WORKSPACE,),
    )
    db.execute(
        """INSERT INTO product_revisions (product_id,revision,data,created_at)
        SELECT id,1,data,updated_at FROM legacy_products"""
    )
    db.execute("INSERT INTO reviews SELECT * FROM legacy_reviews")
    db.execute(
        """INSERT INTO tasks (id,workspace_id,request_id,retry_of,status,input,snapshot,
        template_version,insights,mode,error,created_at,updated_at)
        SELECT id,?,request_id,retry_of,
        CASE WHEN status='running' THEN 'queued' ELSE status END,
        input,snapshot,template_version,insights,mode,error,created_at,created_at
        FROM legacy_tasks""",
        (DEMO_WORKSPACE,),
    )
    db.execute("INSERT INTO events SELECT * FROM legacy_events")
    db.execute(
        """INSERT INTO versions (task_id,version,draft,checks,approved_at,created_at,review_status)
        SELECT task_id,version,draft,checks,approved_at,created_at,
        CASE WHEN approved_at IS NULL THEN 'draft' ELSE 'approved' END FROM legacy_versions"""
    )
